// Fonction pour obtenir une traduction
function getLeonardoAiTranslation(key, lang) {
    if (leonardoaiTranslations[lang] && leonardoaiTranslations[lang][key]) {
        return leonardoaiTranslations[lang][key];
    }
    // Fallback à l'anglais
    if (leonardoaiTranslations.en && leonardoaiTranslations.en[key]) {
        return leonardoaiTranslations.en[key];
    }
    return null;
}

// Appliquer les traductions leonardo-ai
function applyLeonardoAiTranslations(lang) {
    console.log('🔥 Applying leonardo-ai translations for:', lang);

    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');

        // Seulement pour les clés leonardo-ai
        if (key && (key.startsWith('review.leonardo-ai.') || key.startsWith('review.common.'))) {
            const translation = getLeonardoAiTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });

    console.log(`✅ Applied ${count} leonardo-ai translations`);
}

// Auto-appliquer quand la langue change
window.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyLeonardoAiTranslations(lang), 200);
});

// Appliquer au chargement
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyLeonardoAiTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyLeonardoAiTranslations(currentLang);
}

console.log('✅ leonardo-ai i18n loaded');
